PRAGMA foreign_keys=ON;
CREATE TABLE "Company" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"ticker" TEXT NOT NULL,"name" TEXT NOT NULL,"cik" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Company_ticker_key" ON "Company"("ticker");
CREATE TABLE "Filing" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"companyId" INTEGER NOT NULL REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"formType" TEXT NOT NULL,"filingDate" TEXT NOT NULL,"periodEnd" TEXT NOT NULL,"accessionNumber" TEXT NOT NULL,"sourceUrl" TEXT NOT NULL);
CREATE UNIQUE INDEX "Filing_companyId_accessionNumber_key" ON "Filing"("companyId","accessionNumber");
CREATE TABLE "FinancialMetric" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"filingId" INTEGER NOT NULL REFERENCES "Filing"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"metricName" TEXT NOT NULL,"value" REAL NOT NULL,"unit" TEXT NOT NULL,"periodStart" TEXT,"periodEnd" TEXT NOT NULL);
CREATE TABLE "Analysis" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"companyId" INTEGER NOT NULL REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"filingId" INTEGER NOT NULL REFERENCES "Filing"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"cacheKey" TEXT NOT NULL,"financialDataJson" TEXT NOT NULL,"signalsJson" TEXT NOT NULL,"analysisJson" TEXT NOT NULL,"model" TEXT NOT NULL,"generatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Analysis_cacheKey_key" ON "Analysis"("cacheKey");
CREATE TABLE "Evaluation" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"analysisId" INTEGER NOT NULL REFERENCES "Analysis"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"accuracy" INTEGER NOT NULL,"simplicity" INTEGER NOT NULL,"relevance" INTEGER NOT NULL,"evidence" INTEGER NOT NULL,"neutrality" INTEGER NOT NULL,"notes" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
